#!/usr/bin/env python3
"""TK-410 rest3/4: сводка контроля-2 (curve3) и В2/В3/В5 (conv) по каталогам. Без pandas (в npvenv его нет). Вход: каталоги; выход: sum3-ctrl2.csv, sum3-b235.csv (cwd)."""
import sys, glob, os, csv, numpy as np
def rd(f):
    with open(f, newline='') as h: return list(csv.DictReader(h))
def fl(x):
    try: return float(x)
    except (TypeError, ValueError): return float('nan')
dirs = sys.argv[1:]; ctrl = []; b = []; seen = set()
for d in dirs:
    for f in sorted(glob.glob(f'{d}/*-curve3.csv')):
        coin = os.path.basename(f).split('-')[0]
        if coin in seen: continue
        seen.add(coin); r = rd(f)
        q3 = [x for x in r if fl(x['n']) >= 30 and fl(x['n_days']) >= 3 and not np.isnan(fl(x['exc3']))]; nc = len(q3)
        a = [x for x in q3 if fl(x['ci_lo']) > 2.6]
        p = [x for x in a if fl(x['ci3_lo']) > 2.6 and fl(x['perm_p']) * max(nc, 1) < 0.05]
        ctrl.append(dict(coin=coin, rows=len(r), cells=nc, ci_lo_gt26=len(a), pass_ctrl2=sum(fl(x['ci3_lo']) > 2.6 for x in a), pass_ctrl2_perm_bonf=len(p),
                         max_exc3=max(fl(x['exc3']) for x in q3) if nc else float('nan'), max_ci3_lo=max(fl(x['ci3_lo']) for x in q3) if nc else float('nan'),
                         min_perm_p=min(fl(x['perm_p']) for x in q3) if nc else float('nan')))
seenb = set()
for d in dirs:
    for f in sorted(glob.glob(f'{d}/*-conv.csv')):
        coin = os.path.basename(f).split('-')[0]
        if coin in seenb: continue
        seenb.add(coin); c = rd(f)
        if not c: continue
        t = np.array([fl(x['tconv_s']) for x in c]); t = t[~np.isnan(t)]; fs = [x['first'] for x in c]
        b.append(dict(coin=coin, episodes=len(c), conv=len(t), conv_share=len(t) / len(c), t_p50=np.quantile(t, .5) if len(t) else float('nan'), t_p90=np.quantile(t, .9) if len(t) else float('nan'),
                      share_gate_med=float(np.nanmedian([fl(x['share_gate']) for x in c])), gate_first=fs.count('gate') / len(c), pool_first=fs.count('pool') / len(c), none=fs.count('none') / len(c)))
def wr(fn, rows):
    with open(fn, 'w', newline='') as h:
        if rows: w = csv.DictWriter(h, fieldnames=list(rows[0])); w.writeheader(); w.writerows(rows)
    for x in rows: print({k: (round(v, 3) if isinstance(v, float) else v) for k, v in x.items()})
wr('sum3-ctrl2.csv', ctrl); print(); wr('sum3-b235.csv', b)
